// kinetic OpenCode plugin — generated by `kinetic install --harness opencode`.
// Do not edit: reinstall regenerates this file (the clone path is baked in).
//
// Forwards OpenCode tool/session events to the clone's Python hooks
// (`python3 <clone>/hooks/<name>.py --harness opencode`, JSON on stdin) and
// maps their flat {"decision","reason"} output back onto OpenCode:
//   - PreToolUse "deny"  -> throw inside tool.execute.before (tool call fails)
//   - PreToolUse "ask"   -> pending ask consumed by permission.evaluate,
//                          which sets effect="ask" + message so OpenCode's own
//                          permission flow prompts the user
//   - PostToolUse        -> record_edit.py / claim_run.py (fire and forget)
//   - experimental.idle  -> completion_gate.py; a "block" decision re-prompts
//                          the session via ctx.session.synthetic (input admitted
//                          by the idle hook runs in the same execution, so the
//                          agent cannot go idle until it answers; bounded by
//                          IDLE_REPROMPT_LIMIT per session)
//   - session "context"  -> orient.py once a minute per session; the
//                          hookSpecificOutput.additionalContext text is pushed
//                          into the outgoing system prompt
//
// Dependency-free: node builtins only (node:child_process, proven to run in
// OpenCode's plugin host — see rtk.ts). Works on OpenCode v2 (setup/ctx hooks)
// and, best-effort, v1 (server() tool hooks only: deny and recording work,
// ask/orient/idle have no v1 channel and degrade to warnings).

import { execFile } from "node:child_process"

const CLONE = __KINETIC_CLONE__
const HOOK_DIR = CLONE + "/hooks"
const TIMEOUT_MS = 9000
const MAX_STDOUT = 4 * 1024 * 1024
const ORIENT_TTL_MS = 60000
const IDLE_REPROMPT_LIMIT = 3
const PENDING_ASK_LIMIT = 200

// OpenCode v2 tool names -> which kinetic hook scripts apply, mirroring
// hooks/hooks.json matchers. MCP tools arrive namespaced as <server>_<tool>;
// the write-op/deploy patterns are the same ones the Claude matchers use,
// minus the mcp__ prefix.
const EDIT_TOOLS = new Set(["edit", "write", "patch"])
const SHELL_TOOLS = new Set(["shell", "bash"]) // "bash" is the v1 name
const WRITE_OPS_MCP =
  /atlassian.*(create|edit|update|transition|comment|executewrite|executedestructive)|github.*(create_pull_request|merge_pull_request|update_pull_request|push_files|create_or_update_file|create_branch|delete_file)/i
const DEPLOY_MCP = /deploy|tekton.*trigger/

function scriptsFor(tool: unknown, phase: "pre" | "post"): string[] {
  const t = String(tool || "")
  const out: string[] = []
  const isEdit = EDIT_TOOLS.has(t)
  const isShell = SHELL_TOOLS.has(t)
  if (phase === "pre") {
    if (isEdit) out.push("isolation.py")
    if (isShell || WRITE_OPS_MCP.test(t)) out.push("confirm_write_ops.py")
    if (DEPLOY_MCP.test(t)) out.push("confirm_deploy.py")
  } else {
    if (isEdit) out.push("record_edit.py")
    if (isShell) out.push("claim_run.py")
  }
  return out
}

// Spawn `python3 <clone>/hooks/<script> --harness opencode` with the payload
// as JSON stdin; resolves the parsed stdout object or null on any failure
// (spawn error, timeout, non-JSON output). Hooks themselves fail closed where
// it matters; a transport failure stays fail-open like other harnesses.
function callHook(script: string, payload: unknown): Promise<any | null> {
  return new Promise((resolve) => {
    let child: any
    try {
      child = execFile(
        "python3",
        [HOOK_DIR + "/" + script, "--harness", "opencode"],
        { timeout: TIMEOUT_MS, maxBuffer: MAX_STDOUT },
        (_err: any, stdout: any) => {
          try {
            const text = String(stdout || "").trim()
            if (!text) return resolve(null)
            const parsed = JSON.parse(text)
            resolve(parsed && typeof parsed === "object" ? parsed : null)
          } catch {
            resolve(null)
          }
        },
      )
    } catch {
      return resolve(null)
    }
    try {
      child.stdin.write(JSON.stringify(payload ?? {}))
      child.stdin.end()
    } catch {
      /* stdin may already be closed on early spawn failure */
    }
  })
}

// The session's working directory, resolved once per session via
// ctx.session.get -> location.directory (tool events do not carry it).
const cwdCache = new Map<string, Promise<string>>()

function sessionCwd(ctx: any, sessionID: unknown): Promise<string> {
  const key = String(sessionID || "")
  if (!key) return Promise.resolve(process.cwd())
  let hit = cwdCache.get(key)
  if (!hit) {
    hit = (async () => {
      try {
        const s = await ctx.session.get({ sessionID: key })
        const d = s && s.location && s.location.directory
        return typeof d === "string" && d ? d : process.cwd()
      } catch {
        return process.cwd()
      }
    })()
    cwdCache.set(key, hit)
    if (cwdCache.size > 500) {
      cwdCache.delete(cwdCache.keys().next().value as string)
    }
  }
  return hit
}

// ask decisions recorded between tool.execute.before and the tool's own
// permission.assert -> permission.evaluate, correlated by tool call id
// (Permission.Source.id === the execute.before event's id).
const pendingAsks = new Map<string, { sessionID: string; reason: string }>()

function recordAsk(e: any, reason: string) {
  const key = String((e && (e.id || e.callID)) || "")
  if (!key) return
  if (pendingAsks.size >= PENDING_ASK_LIMIT) {
    pendingAsks.delete(pendingAsks.keys().next().value as string)
  }
  pendingAsks.set(key, {
    sessionID: String((e && e.sessionID) || ""),
    reason,
  })
}

function onPermissionEvaluate(e: any) {
  if (!e || typeof e !== "object") return
  const src = e.source
  let key: string | null = null
  let hit: { sessionID: string; reason: string } | undefined
  if (src && src.type === "tool" && src.id != null) {
    key = String(src.id)
    hit = pendingAsks.get(key)
  }
  if (!hit) {
    // No tool source id: escalate only when exactly one ask is pending in
    // this session, so unrelated permission prompts are never hijacked.
    const sid = String(e.sessionID || "")
    const matches = [...pendingAsks.entries()].filter(
      ([, v]) => v.sessionID === sid,
    )
    if (matches.length === 1) {
      key = matches[0][0]
      hit = matches[0][1]
    }
  }
  if (!hit || key === null) return
  pendingAsks.delete(key)
  e.effect = "ask"
  if (hit.reason) e.message = hit.reason
}

async function runPreHooks(ctx: any, e: any, cwd: string) {
  const scripts = scriptsFor(e && e.tool, "pre")
  if (!scripts.length) return
  const payload = {
    kinetic_event: "PreToolUse",
    cwd,
    sessionID: e.sessionID,
    agent: e.agent,
    messageID: e.messageID,
    id: e.id,
    callID: e.id, // v1 spelling, harmless extra field
    tool: e.tool,
    input: e.input,
  }
  let ask: string | null = null
  for (const script of scripts) {
    const out = await callHook(script, payload)
    const decision = out && out.decision
    if (decision === "deny") {
      throw new Error(
        String((out && out.reason) || "kinetic denied this tool call"),
      )
    }
    if (decision === "ask" && ask === null) {
      ask = String((out && out.reason) || "kinetic asks for confirmation")
    }
  }
  if (ask !== null) recordAsk(e, ask)
}

async function preTool(ctx: any, e: any) {
  const scripts = scriptsFor(e && e.tool, "pre")
  if (!scripts.length) return
  const cwd = await sessionCwd(ctx, e && e.sessionID)
  await runPreHooks(ctx, e, cwd)
}

async function postTool(ctx: any, e: any) {
  // Only completed calls: a failed edit did not happen, so it must not
  // stamp last_edit_at (PostToolUseFailure has no Claude equivalent here).
  if (!e || e.status !== "completed") return
  const scripts = scriptsFor(e.tool, "post")
  if (!scripts.length) return
  const cwd = await sessionCwd(ctx, e.sessionID)
  const payload = {
    kinetic_event: "PostToolUse",
    cwd,
    sessionID: e.sessionID,
    agent: e.agent,
    messageID: e.messageID,
    id: e.id,
    tool: e.tool,
    input: e.input,
    status: "completed",
    // result/error bodies are deliberately not forwarded: the recording
    // hooks read only the call input, and tool output can be huge.
  }
  for (const script of scripts) {
    await callHook(script, payload)
  }
}

// Bounded idle re-prompts per session: the gate may fire again after each
// synthetic round; after IDLE_REPROMPT_LIMIT ignored rounds the session is
// left alone (verify/ship still refuse stale verify at the CLI layer).
const idleCounts = new Map<string, number>()

async function onIdle(ctx: any, e: any) {
  const sid = String((e && e.sessionID) || "")
  if (!sid) return
  const cwd = await sessionCwd(ctx, sid)
  const out = await callHook("completion_gate.py", {
    kinetic_event: "Stop",
    sessionID: sid,
    cwd,
    stop_hook_active: false,
  })
  if (out && out.decision === "block" && out.reason) {
    const n = idleCounts.get(sid) || 0
    if (n >= IDLE_REPROMPT_LIMIT) return
    idleCounts.set(sid, n + 1)
    try {
      await ctx.session.synthetic({
        sessionID: sid,
        text: "kinetic verify gate: " + String(out.reason),
        description: "kinetic verify gate",
      })
    } catch (err) {
      console.warn("[kinetic] idle re-prompt failed:", err)
    }
  } else {
    // fresh verify or no active run: restore the reprompt budget
    idleCounts.delete(sid)
  }
}

// orient.py output is Claude-shaped (hookSpecificOutput.additionalContext)
// on every harness; the plugin maps it into the session context hook.
const orientCache = new Map<string, { text: string | null; at: number }>()

async function onContext(_ctx: any, e: any) {
  const sid = String((e && e.sessionID) || "")
  if (!sid || !Array.isArray(e.system)) return
  let cached = orientCache.get(sid)
  if (!cached || Date.now() - cached.at > ORIENT_TTL_MS) {
    const out = await callHook("orient.py", {
      kinetic_event: "SessionStart",
      sessionID: sid,
    })
    const hso = out && out.hookSpecificOutput
    cached = {
      text:
        hso && typeof hso.additionalContext === "string"
          ? hso.additionalContext
          : null,
      at: Date.now(),
    }
    orientCache.set(sid, cached)
    if (orientCache.size > 500) {
      orientCache.delete(orientCache.keys().next().value as string)
    }
  }
  if (cached.text) {
    e.system.push({ type: "text", text: cached.text })
  }
}

async function setupV2(ctx: any) {
  // Every registration is guarded: a missing domain (older v2, API drift)
  // must degrade that feature, never keep the whole plugin from loading.
  try {
    await ctx?.tool?.hook?.("execute.before", (e: any) => preTool(ctx, e))
  } catch (err) {
    console.warn("[kinetic] tool.execute.before unavailable:", err)
  }
  try {
    await ctx?.tool?.hook?.("execute.after", (e: any) => postTool(ctx, e))
  } catch (err) {
    console.warn("[kinetic] tool.execute.after unavailable:", err)
  }
  try {
    await ctx?.permission?.hook?.("evaluate", onPermissionEvaluate)
  } catch (err) {
    console.warn("[kinetic] permission.evaluate unavailable:", err)
  }
  try {
    await ctx?.session?.hook?.("experimental.idle", (e: any) =>
      onIdle(ctx, e),
    )
  } catch (err) {
    console.warn("[kinetic] experimental.idle unavailable:", err)
  }
  try {
    await ctx?.session?.hook?.("context", (e: any) => onContext(ctx, e))
  } catch (err) {
    console.warn("[kinetic] session context unavailable:", err)
  }
}

// OpenCode 1.x entrypoint: tool hooks only, best effort. input carries
// {tool, sessionID, callID}; output.args is the tool input. v1 has no ask
// channel (warn instead) and no idle/context hooks, so the verify gate and
// orientation stay Instructed there.
async function setupV1() {
  return {
    "tool.execute.before": async (input: any, output: any) => {
      const tool = input && input.tool
      const scripts = scriptsFor(tool, "pre")
      if (!scripts.length) return
      const args = (output && output.args) || {}
      const payload = {
        kinetic_event: "PreToolUse",
        cwd: process.cwd(),
        sessionID: input && input.sessionID,
        id: input && input.callID,
        tool,
        input: args,
      }
      let ask: string | null = null
      for (const script of scripts) {
        const out = await callHook(script, payload)
        const decision = out && out.decision
        if (decision === "deny") {
          throw new Error(
            String((out && out.reason) || "kinetic denied this tool call"),
          )
        }
        if (decision === "ask" && ask === null) {
          ask = String((out && out.reason) || "kinetic asks for confirmation")
        }
      }
      if (ask !== null) console.warn("[kinetic] " + ask)
    },
    "tool.execute.after": async (input: any, output: any) => {
      const tool = input && input.tool
      const scripts = scriptsFor(tool, "post")
      if (!scripts.length) return
      const args = (output && output.args) || {}
      const payload = {
        kinetic_event: "PostToolUse",
        cwd: process.cwd(),
        sessionID: input && input.sessionID,
        id: input && input.callID,
        tool,
        input: args,
        status: "completed",
      }
      for (const script of scripts) {
        await callHook(script, payload)
      }
    },
  }
}

// A plain object, because the v2 loader schema-validates `default` against
// `typeof === "object"`. `setup` is the v2 entrypoint; `server` is the v1 one.
const KineticOpenCodePlugin = {
  id: "kinetic",

  async setup(ctx: any) {
    await setupV2(ctx)
  },

  async server() {
    return setupV1()
  },
}

export default KineticOpenCodePlugin
export { KineticOpenCodePlugin }
